CREATE TABLE access_cache(principal TEXT PRIMARY KEY, repositories TEXT NOT NULL, legacy TEXT NOT NULL DEFAULT '[]', refreshed INTEGER NOT NULL, expires INTEGER NOT NULL) /* GitHub-derived repository access per person, short TTL — never a grant supplied by a browser */;
CREATE INDEX access_cache_expiry ON access_cache(expires);
CREATE TABLE tenant_backfill(old_tenant TEXT NOT NULL, repo_id TEXT NOT NULL, name TEXT NOT NULL, branch TEXT NOT NULL, new_tenant TEXT, linked INTEGER, note TEXT, PRIMARY KEY(old_tenant, repo_id)) /* every pre-workspace index, and the workspace it was mapped onto */;
CREATE INDEX tenant_backfill_name ON tenant_backfill(name);
INSERT OR IGNORE INTO tenant_backfill(old_tenant, repo_id, name, branch, note) SELECT tenant, id, name, branch, 'awaiting GitHub owner identity' FROM index_repos WHERE tenant LIKE 'user:%';
SELECT 'Workspaces are keyed by the GitHub account that owns the repository: gh:org:<account id> or gh:user:<account id>. See ownerTenant in cloudflare/onboarding.ts.';
SELECT 'Backfill, part one (above): every index that was created under a per-user tenant user:<clerk sub> is recorded here with the repository it holds. SQL cannot finish the mapping: the workspace key needs the owner account id and type, which only GitHub can supply, and the owner login in name is not proof of either.';
SELECT 'Backfill, part two (runtime): linkLegacyIndexes in cloudflare/onboarding.ts fills new_tenant and linked the first time a person GitHub still grants push access to that repository signs in, and admits the legacy tenant to every such persons scope. From that moment the existing index is shared by everyone GitHub grants the repository to, which is the whole point of the change.';
SELECT 'Limitation, deliberate: the rows of an adopted index are not rewritten to the workspace key. Every indexed files source is an R2 object whose AES-GCM additional data binds it to the tenant it was written under, so rewriting objects.tenant, index_files.tenant or index_blobs.tenant would leave the index pointing at payloads that no longer decrypt. Nothing is dropped — the data stays where it is and stays reachable through the recorded mapping. Physically re-tenanting an index needs a background re-encryption pass that does not exist yet.';
SELECT 'Limitation: audit rows are append-only by trigger, so a legacy tenants audit trail cannot be moved or rewritten at all. It stays under user:<clerk sub> and remains visible to that person.';
SELECT 'Limitation: github-link, oauth_states and agent_tokens are individual credentials and stay under user:<clerk sub> on purpose. They are not workspace data and must never be shared with a workspaces other members.';
SELECT 'Limitation: tasks and changesets created before this migration were stored under the per-user tenant and stay there, for the same AEAD binding reason as source objects. They remain readable to their author — a workspace colleague sees the shared index but not that persons earlier drafts.';
